        --muted: #586277;
        --line: rgba(23, 32, 51, 0.1);
        --accent: #5b7cff;
        --accent-strong: #3d5cf0;
        --shadow: 0 24px 80px rgba(20, 34, 71, 0.12);
        --radius: 24px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(91, 124, 255, 0.16), transparent 30%),
          radial-gradient(circle at top right, rgba(63, 201, 181, 0.12), transparent 24%),
          var(--bg);
        color: var(--text);
      }

      .page-shell {
        min-height: 100vh;
        padding: 48px 20px;
      }

      .app {
        width: min(960px, 100%);
        margin: 0 auto;
        background: var(--panel);
        backdrop-filter: blur(18px);
        border: 1px solid rgba(255, 255, 255, 0.7);
        border-radius: 32px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .hero {
        padding: 56px 32px 28px;
        background:
          linear-gradient(135deg, rgba(91, 124, 255, 0.14), rgba(63, 201, 181, 0.08)),
          var(--panel-strong);
        border-bottom: 1px solid var(--line);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: rgba(91, 124, 255, 0.1);
        color: var(--accent-strong);
        font-size: 0.83rem;
        font-weight: 700;
        letter-spacing: 0.02em;
        text-transform: uppercase;
      }

      h1 {
        margin: 18px 0 12px;
        font-size: clamp(2.2rem, 6vw, 4.2rem);
        line-height: 1.02;
      }

      .hero p {
        margin: 0;
        max-width: 42rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq {
        padding: 28px 20px 32px;
      }

      .example {
        margin: 16px 0;
        border: 1px solid var(--line);
        border-radius: var(--radius);
        background: rgba(255, 255, 255, 0.92);
        box-shadow: 0 12px 32px rgba(20, 34, 71, 0.06);
        overflow: clip;
      }

      .question {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 20px;
        width: 100%;
        padding: 22px 24px;
        border: 0;
        background: transparent;
        color: var(--text);
        text-align: left;
        font: inherit;
        font-size: 1.05rem;
        font-weight: 700;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(91, 124, 255, 0.04);
      }

      .question:focus-visible {
        outline: 3px solid rgba(91, 124, 255, 0.45);
        outline-offset: -3px;
      }

      .icon {
        flex: 0 0 auto;
        width: 2rem;
        height: 2rem;
        display: grid;
        place-items: center;
        border-radius: 999px;
        background: rgba(91, 124, 255, 0.1);
        color: var(--accent-strong);
        transition: transform 180ms ease, background-color 180ms ease;
      }

      .question[aria-expanded="true"] .icon {
        transform: rotate(45deg);
        background: rgba(91, 124, 255, 0.16);
      }

      .details {
        padding: 0 24px 22px;
        color: var(--muted);
        line-height: 1.7;
      }

      .details p,
      .details ul {
        margin: 0;
      }

      .details ul {
        padding-left: 1.2rem;
      }

      .details li + li {
        margin-top: 0.45rem;
      }

      @media (max-width: 640px) {
        .hero {
          padding: 40px 22px 24px;
        }

        .faq {
          padding: 20px 14px 24px;
        }

        .question,
        .details {
          padding-left: 18px;
          padding-right: 18px;
        }
      }
    </style>
  </head>
  <body>
    <div class="page-shell">
      <div id="app"></div>
    </div>

    <script>
      const faqItems = [
        {
          id: "nutrition",
          question: "What should I feed my cat every day?",
          answer:
            "Most cats do best on a complete and balanced cat food that matches their age, size, and activity level. Fresh water should always be available, and treats should stay a small part of their diet."
        },
        {
          id: "sleep",
          question: "Why do cats sleep so much?",
          answer:
            "Cats naturally conserve energy for short bursts of activity, so long naps are normal. Many adult cats sleep between 12 and 16 hours a day, especially when they feel safe and comfortable."
        },
        {
          id: "scratching",
          question: "How can I stop my cat from scratching the couch?",
          answer: [
            "Offer sturdy scratching posts in the rooms your cat uses most.",
            "Place the post near the couch first, then move it gradually once your cat uses it.",
            "Reward scratching the right surface with praise, play, or treats."
          ]
        },
        {
          id: "play",
          question: "How much playtime do indoor cats need?",
          answer:
            "Daily interactive play helps indoor cats stay healthy and mentally engaged. Two or three short sessions with wand toys, balls, or puzzle feeders can make a big difference."
        },
        {
          id: "vet",
          question: "When should I call a vet about my cat?",
          answer:
            "Call a vet if your cat stops eating, has trouble breathing, suddenly hides more than usual, vomits repeatedly, or shows a major change in behavior. Quick advice is best when something feels off."
        }
      ];

      const state = {
        openId: null
      };

      function renderDetailsContent(answer) {
        if (Array.isArray(answer)) {
          return `
            <ul>
              ${answer.map((item) => `<li>${item}</li>`).join("")}
            </ul>
          `;
        }

        return `<p>${answer}</p>`;
      }

      function FAQItem(item) {
        const isOpen = state.openId === item.id;

        return `
          <div class="example">
            <button
              class="question"
              type="button"
              aria-expanded="${isOpen}"
              aria-controls="details-${item.id}"
              id="question-${item.id}"
              data-id="${item.id}"
            >
              <span>${item.question}</span>
              <span class="icon" aria-hidden="true">+</span>
            </button>
            <div
              class="details"
              id="details-${item.id}"
              role="region"
              aria-labelledby="question-${item.id}"
              ${isOpen ? "" : "hidden"}
            >
              ${renderDetailsContent(item.answer)}
            </div>
          </div>
        `;
      }

      function FAQList(items) {
        return `
          <section class="faq" aria-label="Frequently asked questions about cats">
            ${items.map(FAQItem).join("")}
          </section>
        `;
      }

      function Hero() {
        return `
          <header class="hero">
            <div class="eyebrow">Cat care essentials</div>
            <h1>Cat FAQ</h1>
            <p>
              A simple guide to everyday cat questions, presented as a clean,
              product-style accordion. Every answer starts collapsed so people
              can scan quickly and open only what they need.
            </p>
          </header>
        `;
      }

      function App() {
        return `
          <main class="app">
            ${Hero()}
            ${FAQList(faqItems)}
          </main>
        `;
      }

      function mount() {
        const root = document.getElementById("app");
        root.innerHTML = App();

        root.querySelectorAll(".question").forEach((button) => {
          button.addEventListener("click", () => {
            const { id } = button.dataset;
            state.openId = state.openId === id ? null : id;
            mount();
          });
        });
      }

      mount();
    </script>
  </body>
</html>
